    if (!swapped) return read;
    if (read == DomainReading.FIRST_RETURN_TYPE) return DomainReading.SECOND_RETURN_TYPE;
    if (read == DomainReading.SECOND_RETURN_TYPE) return DomainReading.FIRST_RETURN_TYPE;
